package com.discordchat;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

@Getter
@RequiredArgsConstructor
public enum ChatStyle
{
	CHATBOX("Chatbox (Discord icon)"),
	PRIVATE("Private message"),
	FRIENDS_CHAT("Friends chat"),
	CLAN_CHAT("Clan chat"),
	GAME("Game message");

	private final String name;

	@Override
	public String toString()
	{
		return name;
	}
}

package com.discordchat;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Keybind;

@ConfigGroup(DiscordChatConfig.GROUP)
public interface DiscordChatConfig extends Config
{
	String GROUP = "discordchat";

	@ConfigSection(
		name = "Connection",
		description = "Discord bot connection settings",
		position = 0
	)
	String connectionSection = "connection";

	@ConfigSection(
		name = "Display",
		description = "How Discord messages appear in the chatbox",
		position = 1
	)
	String displaySection = "display";

	@ConfigItem(
		keyName = "botToken",
		name = "Bot token",
		description = "Token of your Discord bot (Developer Portal > your app > Bot > Reset Token)",
		secret = true,
		position = 0,
		section = connectionSection
	)
	default String botToken()
	{
		return "";
	}

	@ConfigItem(
		keyName = "allowedServers",
		name = "Server IDs",
		description = "Comma-separated Discord server IDs the plugin may use. Leave blank to allow every server the bot is in. You can also tick servers in the Discord Chat side panel.",
		position = 1,
		section = connectionSection
	)
	default String allowedServers()
	{
		return "";
	}

	@ConfigItem(
		keyName = "channelIds",
		name = "Channel IDs",
		description = "Comma-separated Discord channel IDs to relay. Leave blank to relay every channel the bot can see.",
		position = 2,
		section = connectionSection
	)
	default String channelIds()
	{
		return "";
	}

	@ConfigItem(
		keyName = "sendChannelId",
		name = "Send channel ID",
		description = "Channel that ::d posts to. Leave blank to post to the channel you last received a message from.",
		position = 3,
		section = connectionSection
	)
	default String sendChannelId()
	{
		return "";
	}

	@ConfigItem(
		keyName = "relayDms",
		name = "Relay DMs to bot",
		description = "Show direct messages sent to your bot",
		position = 4,
		section = connectionSection
	)
	default boolean relayDms()
	{
		return true;
	}

	@ConfigItem(
		keyName = "includeRsn",
		name = "Include RSN when sending",
		description = "Prefix messages you send from game with your character name",
		position = 5,
		section = connectionSection
	)
	default boolean includeRsn()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showOnline",
		name = "Show online members",
		description = "Track who's online in your servers (side panel and ::donline). Needs 'Presence Intent' and 'Server Members Intent' turned on for your bot.",
		position = 6,
		section = connectionSection
	)
	default boolean showOnline()
	{
		return true;
	}

	@ConfigItem(
		keyName = "runeliteOnly",
		name = "Only show RuneLite players",
		description = "Online list only shows people whose Discord status says they're playing RuneLite or OSRS, so you know who will see your messages",
		position = 7,
		section = connectionSection
	)
	default boolean runeliteOnly()
	{
		return true;
	}

	@ConfigItem(
		keyName = "toggleKeybind",
		name = "Discord mode hotkey",
		description = "Toggles Discord mode, where everything you type in the chatbox goes to your Discord channel instead of game chat",
		position = 0,
		section = displaySection
	)
	default Keybind toggleKeybind()
	{
		return Keybind.NOT_SET;
	}

	@ConfigItem(
		keyName = "sendPrefix",
		name = "Quick-send prefix",
		description = "Start a chat line with this to send just that message to Discord, like // for clan chat. Leave blank to turn off.",
		position = 1,
		section = displaySection
	)
	default String sendPrefix()
	{
		return "@";
	}

	@ConfigItem(
		keyName = "messageStyle",
		name = "Message style",
		description = "How Discord messages appear. 'Chatbox' shows them like normal public chat with a Discord icon (needs your Public chat filter set to Show all).",
		position = 2,
		section = displaySection
	)
	default ChatStyle chatStyle()
	{
		return ChatStyle.CHATBOX;
	}

	@ConfigItem(
		keyName = "showChannel",
		name = "Show channel name",
		description = "Show which Discord channel a message came from",
		position = 3,
		section = displaySection
	)
	default boolean showChannel()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showServer",
		name = "Show server name",
		description = "Also show which Discord server a message came from",
		position = 4,
		section = displaySection
	)
	default boolean showServer()
	{
		return false;
	}
}

package com.discordchat;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.GridLayout;
import java.util.Collections;
import java.util.List;
import java.util.Objects;
import java.util.function.Predicate;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JCheckBox;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

class DiscordChatPanel extends PluginPanel
{
	private static final int MAX_MEMBERS_SHOWN = 200;
	private static final Color CONNECTED = new Color(0x3b, 0xa5, 0x5d);
	private static final Color DISCONNECTED = new Color(0xed, 0x42, 0x45);

	private final DiscordChatPlugin plugin;
	private final JLabel statusLabel = new JLabel();
	private final JCheckBox modeToggle = new JCheckBox("Talk in Discord instead of game");
	private final JComboBox<DiscordGateway.Channel> channelBox = new JComboBox<>();
	private final JPanel serverPanel = new JPanel();
	private final JPanel onlinePanel = new JPanel();

	private List<DiscordGateway.Channel> shownChannels = Collections.emptyList();
	private boolean updating;

	DiscordChatPanel(DiscordChatPlugin plugin)
	{
		this.plugin = plugin;

		setLayout(new BorderLayout(0, 10));
		setBorder(new EmptyBorder(10, 10, 10, 10));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		JPanel controls = new JPanel(new GridLayout(0, 1, 0, 5));
		controls.setBackground(ColorScheme.DARK_GRAY_COLOR);

		JLabel title = new JLabel("Discord Chat");
		title.setFont(FontManager.getRunescapeBoldFont());
		controls.add(title);
		controls.add(statusLabel);

		JLabel channelLabel = new JLabel("Channel");
		channelLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		controls.add(channelLabel);
		controls.add(channelBox);
		controls.add(modeToggle);

		channelBox.addActionListener(e ->
		{
			DiscordGateway.Channel selected = (DiscordGateway.Channel) channelBox.getSelectedItem();
			if (!updating && selected != null)
			{
				plugin.setActiveChannel(selected.getId());
			}
		});
		modeToggle.setBackground(ColorScheme.DARK_GRAY_COLOR);
		modeToggle.addActionListener(e ->
		{
			if (!updating)
			{
				plugin.setDiscordMode(modeToggle.isSelected());
			}
		});

		serverPanel.setLayout(new BoxLayout(serverPanel, BoxLayout.Y_AXIS));
		serverPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		onlinePanel.setLayout(new BoxLayout(onlinePanel, BoxLayout.Y_AXIS));
		onlinePanel.setBackground(ColorScheme.DARK_GRAY_COLOR);

		JPanel lists = new JPanel(new BorderLayout(0, 10));
		lists.setBackground(ColorScheme.DARK_GRAY_COLOR);
		lists.add(serverPanel, BorderLayout.NORTH);
		lists.add(onlinePanel, BorderLayout.CENTER);

		add(controls, BorderLayout.NORTH);
		add(lists, BorderLayout.CENTER);

		update(false, Collections.emptyList(), id -> true, Collections.emptyList(), null, false, null, true);
	}

	/**
	 * Must be called on the Swing thread.
	 *
	 * @param servers   every server the bot is in
	 * @param allowed   which of those servers the plugin may use
	 * @param channels  channels in allowed servers
	 * @param online    online members of allowed servers, or null if presence tracking is turned off
	 * @param runeliteOnly whether {@code online} only contains people playing RuneLite/OSRS
	 */
	void update(boolean connected, List<DiscordGateway.Server> servers, Predicate<String> allowed,
		List<DiscordGateway.Channel> channels, String activeChannelId, boolean discordMode,
		List<DiscordGateway.OnlineGuild> online, boolean runeliteOnly)
	{
		updating = true;
		try
		{
			statusLabel.setText(connected ? "Connected" : "Not connected");
			statusLabel.setForeground(connected ? CONNECTED : DISCONNECTED);
			modeToggle.setSelected(discordMode);

			if (!channels.equals(shownChannels))
			{
				shownChannels = channels;
				channelBox.removeAllItems();
				channels.forEach(channelBox::addItem);
			}
			channelBox.setSelectedItem(null);
			for (DiscordGateway.Channel c : channels)
			{
				if (Objects.equals(c.getId(), activeChannelId))
				{
					channelBox.setSelectedItem(c);
				}
			}

			rebuildServers(servers, allowed);
			rebuildOnline(online, runeliteOnly);
		}
		finally
		{
			updating = false;
		}
	}

	private void rebuildServers(List<DiscordGateway.Server> servers, Predicate<String> allowed)
	{
		serverPanel.removeAll();
		if (!servers.isEmpty())
		{
			JLabel header = new JLabel("Servers");
			header.setFont(FontManager.getRunescapeBoldFont());
			serverPanel.add(header);

			for (DiscordGateway.Server server : servers)
			{
				JCheckBox box = new JCheckBox(server.getName(), allowed.test(server.getId()));
				box.setBackground(ColorScheme.DARK_GRAY_COLOR);
				box.setToolTipText("Untick to ignore this server: no messages, channels or online list from it");
				box.addActionListener(e -> plugin.setServerAllowed(server.getId(), box.isSelected()));
				serverPanel.add(box);
			}
		}
		serverPanel.revalidate();
		serverPanel.repaint();
	}

	private void rebuildOnline(List<DiscordGateway.OnlineGuild> online, boolean runeliteOnly)
	{
		onlinePanel.removeAll();

		if (online == null)
		{
			onlinePanel.add(new JLabel("<html>Turn on 'Show online members' in the plugin settings to see who's online.</html>"));
		}
		else
		{
			for (DiscordGateway.OnlineGuild guild : online)
			{
				JLabel header = new JLabel("<html>" + escape(guild.getName()) + " - " + guild.getMembers().size() + (runeliteOnly ? " in RuneLite" : " online") + "</html>");
				header.setFont(FontManager.getRunescapeBoldFont());
				header.setBorder(BorderFactory.createEmptyBorder(8, 0, 2, 0));
				onlinePanel.add(header);

				List<DiscordGateway.OnlineMember> members = guild.getMembers();
				for (int i = 0; i < members.size() && i < MAX_MEMBERS_SHOWN; i++)
				{
					DiscordGateway.OnlineMember member = members.get(i);
					String game = member.getGame() == null || member.getGame().isEmpty() ? ""
						: " <font color='#8f8f8f'>" + escape(member.getGame()) + "</font>";
					JLabel line = new JLabel("<html><font color='" + statusColor(member.getStatus()) + "'>●</font> "
						+ escape(member.getName()) + game + "</html>");
					line.setToolTipText(member.getGame() == null ? null : "Playing RuneLite" + (game.isEmpty() ? "" : ": " + member.getGame()));
					onlinePanel.add(line);
				}
				if (members.size() > MAX_MEMBERS_SHOWN)
				{
					onlinePanel.add(new JLabel("...and " + (members.size() - MAX_MEMBERS_SHOWN) + " more"));
				}
			}
		}

		onlinePanel.revalidate();
		onlinePanel.repaint();
	}

	private static String statusColor(String status)
	{
		switch (status)
		{
			case "online":
				return "#3ba55d";
			case "idle":
				return "#faa81a";
			default:
				return "#ed4245";
		}
	}

	private static String escape(String s)
	{
		return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}
}

package com.discordchat;

import com.google.gson.Gson;
import com.google.inject.Provides;
import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.Arrays;
import java.util.Collections;
import java.util.Deque;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import java.util.concurrent.ConcurrentLinkedDeque;
import java.util.function.BooleanSupplier;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.IndexedSprite;
import net.runelite.api.Menu;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.MessageNode;
import net.runelite.api.Player;
import net.runelite.api.events.CommandExecuted;
import net.runelite.api.events.MenuOpened;
import net.runelite.api.events.ScriptCallbackEvent;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ChatboxInput;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.input.KeyManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.HotkeyListener;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.Text;
import okhttp3.OkHttpClient;

@Slf4j
@PluginDescriptor(
	name = "Discord Chat",
	description = "Brings Discord channels into your chatbox. @message or ::d to send, ::dc or right-click the Clan tab to talk in Discord",
	tags = {"discord", "chat", "pm", "social", "bridge", "clan"}
)
public class DiscordChatPlugin extends Plugin
{
	private static final String SEND_COMMAND = "d";
	private static final String REPLY_COMMAND = "dr";
	private static final String MODE_COMMAND = "dc";
	private static final String ONLINE_COMMAND = "donline";
	private static final String BLURPLE = "5865f2";
	private static final Color BLURPLE_COLOR = new Color(0x58, 0x65, 0xf2);
	private static final Pattern RSN_PREFIX = Pattern.compile("^[*][*](.+?)[*][*]: (.*)$");
	private static final int RECENTLY_SENT_LIMIT = 20;
	private static final int MAX_MENU_CHANNELS = 25;
	private static final long RESEND_POST_AFTER_MS = 5_000;
	private static final long RESEND_BLOCK_FOR_MS = 60_000;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private DiscordChatConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private OkHttpClient okHttpClient;

	@Inject
	private Gson gson;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private KeyManager keyManager;

	@Inject
	private DiscordModeOverlay overlay;

	private DiscordGateway gateway;
	private DiscordChatPanel panel;
	private NavigationButton navButton;
	private Timer panelRefresh;

	/** Index of our Discord icon in the client's chat icons, usable as &lt;img=N&gt;. -1 until loaded. */
	private int iconIndex = -1;

	@Getter
	private volatile boolean discordMode;
	private volatile String activeChannelId;
	private volatile String lastChannelId;
	// Messages this client posted, so they aren't shown twice when Discord echoes them back
	private final Deque<String> recentlySent = new ConcurrentLinkedDeque<>();
	// Chat command handling, see onScriptCallbackEvent. Client thread only.
	private HeldCommand heldCommand;
	private HeldCommand awaitingResend;

	private final HotkeyListener toggleHotkey = new HotkeyListener(() -> config.toggleKeybind())
	{
		@Override
		public void hotkeyPressed()
		{
			clientThread.invokeLater(() -> setDiscordMode(!discordMode));
		}
	};

	@Provides
	DiscordChatConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(DiscordChatConfig.class);
	}

	@Override
	protected void startUp()
	{
		panel = new DiscordChatPanel(this);
		navButton = NavigationButton.builder()
			.tooltip("Discord Chat")
			.icon(createIcon(16))
			.priority(10)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		// Presence updates can be very chatty, so refresh the panel at most twice a second
		panelRefresh = new Timer(500, e -> refreshPanelNow());
		panelRefresh.setRepeats(false);

		overlayManager.add(overlay);
		keyManager.registerKeyListener(toggleHotkey);
		clientThread.invoke(this::loadChatIcon);

		String sendChannel = config.sendChannelId().trim();
		activeChannelId = sendChannel.isEmpty() ? null : sendChannel;

		connect();
	}

	@Override
	protected void shutDown()
	{
		disconnect();
		keyManager.unregisterKeyListener(toggleHotkey);
		overlayManager.remove(overlay);
		clientToolbar.removeNavigation(navButton);
		panelRefresh.stop();
		panel = null;
		discordMode = false;
		activeChannelId = null;
		lastChannelId = null;
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!DiscordChatConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}

		switch (event.getKey())
		{
			case "botToken":
			case "showOnline":
				disconnect();
				connect();
				break;
			case "sendChannelId":
				String sendChannel = config.sendChannelId().trim();
				if (!sendChannel.isEmpty())
				{
					activeChannelId = sendChannel;
				}
				refreshPanel();
				break;
			default:
				refreshPanel();
				break;
		}
	}

	private void connect()
	{
		String token = config.botToken().trim();
		if (token.isEmpty())
		{
			refreshPanel();
			return;
		}

		gateway = new DiscordGateway(okHttpClient, gson, token, config.showOnline(), new DiscordGateway.Listener()
		{
			@Override
			public void onMessage(DiscordMessage message)
			{
				onDiscordMessage(message);
			}

			@Override
			public void onStatus(String status)
			{
				status(status);
			}

			@Override
			public void onStateChanged()
			{
				refreshPanel();
			}
		});
		gateway.start();
	}

	private void disconnect()
	{
		if (gateway != null)
		{
			gateway.stop();
			gateway = null;
		}
		refreshPanel();
	}

	// ---- server / channel filtering ----

	private boolean isServerAllowed(String guildId)
	{
		List<String> allowed = Text.fromCSV(config.allowedServers());
		return allowed.isEmpty() || allowed.contains(guildId);
	}

	private boolean isChannelAllowed(String channelId)
	{
		DiscordGateway gw = gateway;
		String guildId = gw == null ? null : gw.guildOf(channelId);
		if (guildId != null && !isServerAllowed(guildId))
		{
			return false;
		}
		List<String> allowed = Text.fromCSV(config.channelIds());
		return allowed.isEmpty() || allowed.contains(channelId);
	}

	/**
	 * Allows or blocks a server. Called from the side panel.
	 */
	void setServerAllowed(String guildId, boolean allowed)
	{
		DiscordGateway gw = gateway;
		if (gw == null)
		{
			return;
		}

		List<String> allIds = gw.servers().stream().map(DiscordGateway.Server::getId).collect(Collectors.toList());
		List<String> current = Text.fromCSV(config.allowedServers());
		Set<String> ids = new LinkedHashSet<>(current.isEmpty() ? allIds : current);
		if (allowed)
		{
			ids.add(guildId);
		}
		else
		{
			ids.remove(guildId);
		}

		// Blank means "every server", which also covers servers the bot joins later
		String value = ids.containsAll(allIds) ? "" : String.join(",", ids);
		configManager.setConfiguration(DiscordChatConfig.GROUP, "allowedServers", value);

		if (!allowed && activeChannelId != null && guildId.equals(gw.guildOf(activeChannelId)))
		{
			activeChannelId = null;
			if (discordMode)
			{
				setDiscordMode(false);
			}
		}
	}

	private List<DiscordGateway.Channel> allowedChannels()
	{
		DiscordGateway gw = gateway;
		if (gw == null)
		{
			return Collections.emptyList();
		}
		return gw.textChannels().stream()
			.filter(c -> isChannelAllowed(c.getId()))
			.collect(Collectors.toList());
	}

	// ---- incoming ----

	// Called on the gateway thread
	private void onDiscordMessage(DiscordMessage received)
	{
		DiscordMessage message = received;
		if (received.isFromBot())
		{
			if (recentlySent.remove(received.getContent()))
			{
				return; // our own message echoed back
			}
			// Sent by someone else sharing this bot token: show it under their RSN instead of the bot's name
			Matcher m = RSN_PREFIX.matcher(received.getContent());
			if (m.matches())
			{
				message = new DiscordMessage(received.getChannelId(), received.getGuildId(), received.isDirect(),
					true, m.group(1), true, m.group(2));
			}
		}

		if (message.isDirect())
		{
			if (!config.relayDms())
			{
				return;
			}
		}
		else if (!isServerAllowed(message.getGuildId()) || !isChannelAllowed(message.getChannelId()))
		{
			return;
		}

		lastChannelId = message.getChannelId();
		DiscordMessage shown = message;
		clientThread.invokeLater(() -> showIncoming(shown));
	}

	private void showIncoming(DiscordMessage message)
	{
		DiscordGateway gw = gateway;
		String label = message.isDirect() || gw == null ? "DM" : gw.channelLabel(message.getChannelId(), config.showServer());
		String author = escape(message.getAuthor());
		String text = escape(message.getContent());

		// DMs always look like private messages
		if (message.isDirect() || config.chatStyle() == ChatStyle.PRIVATE)
		{
			boolean suffix = config.showChannel() && !message.isDirect();
			String from = chatName(author, escape(label), suffix, message.isAuthorIsRsn(), message.getContent());
			client.addChatMessage(ChatMessageType.PRIVATECHAT, icon() + from, text, null);
		}
		else
		{
			addChannelMessage(author, escape(label), text, message.isAuthorIsRsn(), message.getContent());
		}
	}

	/**
	 * The sender name for a chat line. RuneLite's Chat Commands plugin answers lines like "!kc zulrah" by looking
	 * up the sender's name, so command lines from a real OSRS name use the bare name, and command lines from
	 * Discord-only users always keep the channel suffix so they can't match some unrelated player.
	 */
	private static String chatName(String author, String label, boolean suffix, boolean authorIsRsn, String rawText)
	{
		if (rawText.startsWith("!"))
		{
			suffix = !authorIsRsn;
		}
		return suffix ? author + " (" + label + ")" : author;
	}

	private MessageNode showOutgoing(String channelId, String text)
	{
		String label = escape(gateway.channelLabel(channelId, config.showServer()));
		boolean direct = gateway.guildOf(channelId) == null;
		if (direct || config.chatStyle() == ChatStyle.PRIVATE)
		{
			return client.addChatMessage(ChatMessageType.PRIVATECHATOUT, icon() + label, escape(text), null);
		}
		String rsn = localName();
		return addChannelMessage(escape(rsn == null ? "You" : rsn), label, escape(text), rsn != null, text);
	}

	/**
	 * Shows a line in the chatbox, friends chat, clan chat or game message style. All arguments must already be escaped.
	 */
	private MessageNode addChannelMessage(String author, String label, String text, boolean authorIsRsn, String rawText)
	{
		String sender = config.showChannel() ? label : "Discord";
		switch (config.chatStyle())
		{
			case CHATBOX:
				// Looks like normal public chat: "<discord icon>Bob (#general): hi"
				String name = chatName(author, label, config.showChannel(), authorIsRsn, rawText);
				return client.addChatMessage(ChatMessageType.PUBLICCHAT, icon() + name, text, null);
			case FRIENDS_CHAT:
				return client.addChatMessage(ChatMessageType.FRIENDSCHAT,
					icon() + chatName(author, label, false, authorIsRsn, rawText), text, sender);
			case CLAN_CHAT:
				return client.addChatMessage(ChatMessageType.CLAN_CHAT,
					icon() + chatName(author, label, false, authorIsRsn, rawText), text, sender);
			default:
				return client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
					icon() + "<col=" + BLURPLE + ">[" + sender + "]</col> " + author + ": " + text, null);
		}
	}

	// ---- outgoing ----

	/**
	 * Sends a chat line to Discord instead of the game when Discord mode is on, or when it starts with the
	 * quick-send prefix.
	 * <p>
	 * This runs on the raw "chatboxInput" script callback, before RuneLite turns it into a ChatboxInput event
	 * (priority 1 beats RuneLite's own handler at 0). Blanking the line here means the game sends nothing and no
	 * other plugin sees it.
	 * <p>
	 * Chat commands like "!kc zulrah" are the exception. RuneLite's Chat Commands plugin uploads your kill count
	 * or personal best when you type one, so lookups find your latest numbers. We let it see the line, and it
	 * then resends the line to game chat once the upload finishes. That resend comes back through this same
	 * callback, where it's caught, blanked and posted to Discord instead.
	 */
	@Subscribe(priority = 1)
	public void onScriptCallbackEvent(ScriptCallbackEvent event)
	{
		if (!"chatboxInput".equals(event.getEventName()))
		{
			return;
		}

		Object[] stack = client.getObjectStack();
		int size = client.getObjectStackSize();
		if (size < 1 || !(stack[size - 1] instanceof String))
		{
			return;
		}

		String text = (String) stack[size - 1];

		// A chat command coming back from Chat Commands after its upload: post it to Discord, never to the game
		HeldCommand resend = awaitingResend;
		if (resend != null && text.equals(resend.text))
		{
			stack[size - 1] = "";
			awaitingResend = null;
			if (!resend.posted)
			{
				send(resend.channelId, resend.text);
			}
			return;
		}

		if (text.startsWith("::"))
		{
			return;
		}

		String prefix = config.sendPrefix().trim();
		boolean quickSend = !prefix.isEmpty() && text.startsWith(prefix);
		if (!discordMode && !quickSend)
		{
			return;
		}

		String message = (quickSend ? text.substring(prefix.length()) : text).trim();
		String channelId = activeChannelId != null ? activeChannelId : lastChannelId;

		if (message.length() > 1 && message.startsWith("!"))
		{
			// Hand the bare command (without the quick-send prefix) to Chat Commands; see onChatboxInput
			stack[size - 1] = message;
			heldCommand = new HeldCommand(message, channelId);
			return;
		}

		stack[size - 1] = ""; // the game and other plugins now see an empty line, which sends nothing
		if (!message.isEmpty())
		{
			send(channelId, message);
		}
	}

	/**
	 * Runs after every other ChatboxInput subscriber, including RuneLite's Chat Commands, for a chat command we
	 * let through in {@link #onScriptCallbackEvent}.
	 */
	@Subscribe(priority = -100)
	public void onChatboxInput(ChatboxInput input)
	{
		HeldCommand held = heldCommand;
		heldCommand = null;
		if (held == null || !input.getValue().equals(held.text))
		{
			return;
		}

		if (!input.isConsumed())
		{
			// No upload for this command: take it now, so the game never sends it
			input.consume();
			send(held.channelId, held.text);
			return;
		}

		// Chat Commands is uploading and will resend the line when it's done. Catch that resend; if it's slow,
		// post to Discord anyway after a few seconds, but keep blocking a late resend for a while longer.
		awaitingResend = held;
		clientThread.invokeLater((BooleanSupplier) () ->
		{
			if (awaitingResend != held)
			{
				return true;
			}
			long waited = System.currentTimeMillis() - held.createdAt;
			if (!held.posted && waited > RESEND_POST_AFTER_MS)
			{
				held.posted = true;
				send(held.channelId, held.text);
			}
			if (waited > RESEND_BLOCK_FOR_MS)
			{
				awaitingResend = null;
				return true;
			}
			return false;
		});
	}

	/**
	 * A chat command headed for Discord that we let RuneLite's Chat Commands plugin see first.
	 */
	private static final class HeldCommand
	{
		private final String text;
		private final String channelId;
		private final long createdAt = System.currentTimeMillis();
		private boolean posted;

		private HeldCommand(String text, String channelId)
		{
			this.text = text;
			this.channelId = channelId;
		}
	}

	@Subscribe
	public void onCommandExecuted(CommandExecuted event)
	{
		String command = event.getCommand().toLowerCase();
		String args = String.join(" ", event.getArguments()).trim();

		switch (command)
		{
			case SEND_COMMAND:
			case REPLY_COMMAND:
				if (args.isEmpty())
				{
					status("Usage: ::d <message> posts to your current channel, ::dr <message> replies to the last message.");
					return;
				}
				String target = command.equals(REPLY_COMMAND) || activeChannelId == null ? lastChannelId : activeChannelId;
				send(target, args);
				break;
			case MODE_COMMAND:
				if (args.isEmpty())
				{
					setDiscordMode(!discordMode);
				}
				else
				{
					switchChannel(args);
				}
				break;
			case ONLINE_COMMAND:
				printOnline();
				break;
		}
	}

	private void send(String channelId, String text)
	{
		if (gateway == null)
		{
			status("Not connected. Add your bot token in the Discord Chat plugin settings.");
			return;
		}
		if (channelId == null)
		{
			status("No channel picked. Right-click the Clan tab, use ::dc <channel name>, or pick one in the side panel.");
			return;
		}
		if (gateway.guildOf(channelId) != null && !isChannelAllowed(channelId))
		{
			status("That channel's server is turned off in the plugin. Pick another channel.");
			return;
		}

		String rsn = localName();
		String outgoing = config.includeRsn() && rsn != null ? "**" + rsn + "**: " + text : text;
		recentlySent.addLast(outgoing);
		while (recentlySent.size() > RECENTLY_SENT_LIMIT)
		{
			recentlySent.pollFirst();
		}
		MessageNode echo = showOutgoing(channelId, text);
		if (text.startsWith("!") && echo != null)
		{
			// Let RuneLite's Chat Commands plugin answer it in our chatbox, then add the answer on Discord
			PendingCommand pending = new PendingCommand(gateway, channelId, outgoing, echo);
			gateway.sendMessage(channelId, outgoing, error -> status("Couldn't send message: " + error), id -> pending.messageId = id);
			clientThread.invokeLater((BooleanSupplier) pending::check);
		}
		else
		{
			gateway.sendMessage(channelId, outgoing, error -> status("Couldn't send message: " + error), null);
		}
	}

	/**
	 * A "!kc zulrah"-style line we sent to Discord. RuneLite's Chat Commands plugin fills in the answer on our
	 * chat line a moment later; once it does, the Discord message is edited to include it.
	 */
	private static final class PendingCommand
	{
		private static final long TIMEOUT_MS = 10_000;

		private final DiscordGateway gateway;
		private final String channelId;
		private final String outgoing;
		private final MessageNode node;
		private final long deadline = System.currentTimeMillis() + TIMEOUT_MS;
		private volatile String messageId;

		private PendingCommand(DiscordGateway gateway, String channelId, String outgoing, MessageNode node)
		{
			this.gateway = gateway;
			this.channelId = channelId;
			this.outgoing = outgoing;
			this.node = node;
		}

		/**
		 * Runs on the client thread each tick until it returns true.
		 */
		private boolean check()
		{
			if (System.currentTimeMillis() > deadline)
			{
				return true; // not a recognised command, or the lookup failed
			}
			String answer = node.getRuneLiteFormatMessage();
			if (answer == null || messageId == null)
			{
				return false;
			}
			gateway.editMessage(channelId, messageId, outgoing + " \u2192 " + Text.removeTags(answer), error -> { });
			return true;
		}
	}

	// ---- right-click menu on the Clan / Channel chat tabs ----

	@Subscribe
	public void onMenuOpened(MenuOpened event)
	{
		if (gateway == null || !isChatTabMenu(event.getMenuEntries()))
		{
			return;
		}

		Menu menu = client.getMenu();
		List<DiscordGateway.Channel> channels = allowedChannels();
		boolean oneServer = channels.stream().map(DiscordGateway.Channel::getGuildId).distinct().count() <= 1;

		if (!channels.isEmpty())
		{
			MenuEntry parent = menu.createMenuEntry(-1)
				.setOption("<col=" + BLURPLE + ">Discord channel</col>")
				.setTarget("")
				.setType(MenuAction.RUNELITE);
			Menu channelMenu = parent.createSubMenu();
			for (DiscordGateway.Channel channel : channels.subList(0, Math.min(channels.size(), MAX_MENU_CHANNELS)))
			{
				String name = oneServer ? "#" + channel.getName() : channel.getGuildName() + " #" + channel.getName();
				channelMenu.createMenuEntry(-1)
					.setOption((channel.getId().equals(activeChannelId) ? "✓ " : "") + name)
					.setTarget("")
					.setType(MenuAction.RUNELITE)
					.onClick(e ->
					{
						activeChannelId = channel.getId();
						setDiscordMode(true);
					});
			}
		}

		menu.createMenuEntry(-1)
			.setOption(discordMode ? "Stop talking in Discord" : "Talk in Discord")
			.setTarget("<col=" + BLURPLE + ">" + getActiveChannelLabel() + "</col>")
			.setType(MenuAction.RUNELITE)
			.onClick(e -> setDiscordMode(!discordMode));
	}

	private static boolean isChatTabMenu(MenuEntry[] entries)
	{
		for (MenuEntry entry : entries)
		{
			int widgetId = entry.getParam1();
			if (widgetId == InterfaceID.Chatbox.CHAT_CLAN || widgetId == InterfaceID.Chatbox.CHAT_FRIENDSCHAT)
			{
				return true;
			}
		}
		return false;
	}

	// ---- Discord mode / channel switching ----

	/**
	 * Turns Discord mode on or off. Safe to call from any thread.
	 */
	void setDiscordMode(boolean enabled)
	{
		if (enabled && (activeChannelId == null || !isChannelAllowed(activeChannelId)))
		{
			activeChannelId = lastChannelId != null && isChannelAllowed(lastChannelId) ? lastChannelId : firstChannelId();
			if (activeChannelId == null)
			{
				status("No channel to talk in yet. Right-click the Clan tab, use ::dc <channel name>, or pick one in the side panel.");
				refreshPanel();
				return;
			}
		}

		discordMode = enabled;
		status(enabled
			? "Now talking in " + getActiveChannelLabel() + ". Type ::dc or right-click the Clan tab to switch back."
			: "Stopped talking in Discord. Your chat goes to the game again.");
		refreshPanel();
	}

	/**
	 * Selects the channel Discord mode and ::d post to. Safe to call from any thread.
	 */
	void setActiveChannel(String channelId)
	{
		activeChannelId = channelId;
		if (discordMode)
		{
			status("Now talking in " + getActiveChannelLabel() + ".");
		}
		refreshPanel();
	}

	private void switchChannel(String query)
	{
		if (gateway == null)
		{
			status("Not connected. Add your bot token in the Discord Chat plugin settings.");
			return;
		}

		String q = query.toLowerCase().replaceFirst("^#", "");
		DiscordGateway.Channel match = null;
		for (DiscordGateway.Channel c : allowedChannels())
		{
			String name = c.getName().toLowerCase();
			if (name.equals(q) || c.getId().equals(q))
			{
				match = c;
				break;
			}
			if (match == null && name.contains(q))
			{
				match = c;
			}
		}

		if (match == null)
		{
			status("No channel called '" + query + "'.");
			return;
		}

		activeChannelId = match.getId();
		setDiscordMode(true);
	}

	String getActiveChannelLabel()
	{
		DiscordGateway gw = gateway;
		String id = activeChannelId;
		if (id == null)
		{
			return "no channel";
		}
		return gw == null ? id : gw.channelLabel(id, config.showServer());
	}

	private String firstChannelId()
	{
		List<DiscordGateway.Channel> channels = allowedChannels();
		return channels.isEmpty() ? null : channels.get(0).getId();
	}

	// ---- who's online ----

	private void printOnline()
	{
		DiscordGateway gw = gateway;
		if (gw == null || !gw.isConnected())
		{
			status("Not connected to Discord.");
			return;
		}
		if (!config.showOnline())
		{
			status("Turn on 'Show online members' in the plugin settings first.");
			return;
		}

		String what = config.runeliteOnly() ? "in RuneLite" : "online";
		for (DiscordGateway.OnlineGuild guild : visibleOnline(gw))
		{
			String names = guild.getMembers().stream()
				.limit(40)
				.map(m -> m.getGame() == null || m.getGame().isEmpty() ? m.getName() : m.getName() + " (" + m.getGame() + ")")
				.collect(Collectors.joining(", "));
			if (guild.getMembers().size() > 40)
			{
				names += ", ...";
			}
			status(guild.getName() + " (" + guild.getMembers().size() + " " + what + "): " + (names.isEmpty() ? "nobody" : names));
		}
	}

	/**
	 * Online members of allowed servers, limited to people playing RuneLite/OSRS when that setting is on.
	 */
	private List<DiscordGateway.OnlineGuild> visibleOnline(DiscordGateway gw)
	{
		boolean runeliteOnly = config.runeliteOnly();
		return gw.onlineMembers().stream()
			.filter(g -> isServerAllowed(g.getId()))
			.map(g -> !runeliteOnly ? g : new DiscordGateway.OnlineGuild(g.getId(), g.getName(),
				g.getMembers().stream().filter(m -> m.getGame() != null).collect(Collectors.toList())))
			.collect(Collectors.toList());
	}

	// ---- panel ----

	private void refreshPanel()
	{
		SwingUtilities.invokeLater(() ->
		{
			if (panelRefresh != null && !panelRefresh.isRunning())
			{
				panelRefresh.start();
			}
		});
	}

	private void refreshPanelNow()
	{
		DiscordGateway gw = gateway;
		if (panel == null)
		{
			return;
		}

		List<DiscordGateway.OnlineGuild> online = gw != null && config.showOnline() ? visibleOnline(gw) : null;

		panel.update(
			gw != null && gw.isConnected(),
			gw == null ? Collections.emptyList() : gw.servers(),
			this::isServerAllowed,
			allowedChannels(),
			activeChannelId,
			discordMode,
			online,
			config.runeliteOnly());
	}

	// ---- icons ----

	/**
	 * Adds the Discord icon to the client's chat icons (the same list ironman and mod crowns use), so chat
	 * lines can show it with &lt;img=N&gt;. Retried by the client thread until the icons have loaded.
	 */
	private boolean loadChatIcon()
	{
		if (iconIndex >= 0)
		{
			return true;
		}
		IndexedSprite[] modIcons = client.getModIcons();
		if (modIcons == null)
		{
			return false;
		}

		IndexedSprite[] icons = Arrays.copyOf(modIcons, modIcons.length + 1);
		icons[modIcons.length] = ImageUtil.getImageIndexedSprite(createChatIcon(), client);
		client.setModIcons(icons);
		iconIndex = modIcons.length;
		return true;
	}

	private String icon()
	{
		return iconIndex >= 0 ? "<img=" + iconIndex + ">" : "";
	}

	/**
	 * A small Discord-style face: blurple rounded body with two eyes. Drawn without anti-aliasing because chat
	 * icons only support fully opaque or fully transparent pixels.
	 */
	private static BufferedImage createChatIcon()
	{
		BufferedImage image = new BufferedImage(13, 11, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.setColor(BLURPLE_COLOR);
		g.fillRoundRect(0, 0, 13, 11, 6, 6);
		g.setColor(Color.WHITE);
		g.fillRect(3, 4, 2, 3);
		g.fillRect(8, 4, 2, 3);
		g.dispose();
		return image;
	}

	private static BufferedImage createIcon(int size)
	{
		BufferedImage image = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		g.setColor(BLURPLE_COLOR);
		g.fillRoundRect(0, 1, size, size - 2, 6, 6);
		g.setColor(Color.WHITE);
		g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 11));
		FontMetrics fm = g.getFontMetrics();
		g.drawString("D", (size - fm.stringWidth("D")) / 2, 12);
		g.dispose();
		return image;
	}

	// ---- helpers ----

	private String localName()
	{
		Player local = client.getLocalPlayer();
		return local == null || local.getName() == null ? null : Text.sanitize(local.getName());
	}

	/**
	 * Shows a [Discord] notice in the chatbox. Waits until you're logged in, because some plugins (like Loot
	 * Tracker) error on chat messages that arrive at the login screen.
	 */
	private void status(String message)
	{
		clientThread.invokeLater((BooleanSupplier) () ->
		{
			if (client.getGameState() != GameState.LOGGED_IN || client.getLocalPlayer() == null)
			{
				return false;
			}
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
				icon() + "<col=" + BLURPLE + ">[Discord]</col> " + escape(message), null);
			return true;
		});
	}

	/**
	 * Stops Discord text from being interpreted as chatbox formatting tags like &lt;col&gt; or &lt;img&gt;.
	 */
	private static String escape(String text)
	{
		return text.replace("<", "<lt>").replace(">", "<gt>");
	}
}

